import { APP_REGISTRY } from '../data/appRegistry';
import type { AppManifest } from '../types/manifest';
import { debouncedSetItem, cancelPending } from '../debouncedPersist';
import {
  buildDefaultLauncherLayout,
  normalizeLauncherLayout,
  reconcileLauncherLayoutWithRegistry,
} from './layout';
import {
  LAUNCHER_LAYOUT_VERSION,
  LAUNCHER_STORAGE_KEY,
  type LauncherLayout,
} from './types';

function safeJsonParse(raw: string): any | null {
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

export function loadLauncherLayout(appRegistry: AppManifest[] = APP_REGISTRY): LauncherLayout {
  const raw = localStorage.getItem(LAUNCHER_STORAGE_KEY);
  if (!raw) {
    const layout = buildDefaultLauncherLayout(appRegistry);
    saveLauncherLayout(layout);
    return layout;
  }

  const parsed = safeJsonParse(raw);
  if (!parsed || parsed.version !== LAUNCHER_LAYOUT_VERSION) {
    const layout = buildDefaultLauncherLayout(appRegistry);
    saveLauncherLayout(layout);
    return layout;
  }

  // Normalize + reconcile against current registry (for forward compatibility).
  const normalized = normalizeLauncherLayout(parsed as LauncherLayout, appRegistry);
  const reconciled = reconcileLauncherLayoutWithRegistry(normalized, appRegistry);
  // Persist back if changed shape (best-effort).
  saveLauncherLayout(reconciled);
  return reconciled;
}

export function saveLauncherLayout(layout: LauncherLayout): void {
  debouncedSetItem(LAUNCHER_STORAGE_KEY, JSON.stringify(layout));
}

export function clearLauncherLayout(): void {
  cancelPending(LAUNCHER_STORAGE_KEY);
  try {
    localStorage.removeItem(LAUNCHER_STORAGE_KEY);
  } catch {
    // ignore
  }
}

export function resetLauncherLayout(appRegistry: AppManifest[] = APP_REGISTRY): LauncherLayout {
  const layout = buildDefaultLauncherLayout(appRegistry);
  saveLauncherLayout(layout);
  return layout;
}
import type { AppId } from '../types';

export const LAUNCHER_LAYOUT_VERSION = 1 as const;
export const LAUNCHER_STORAGE_KEY = 'launcher' as const;

export type LauncherGrid = {
  columns: number; // system dump: 4
  rows: number;    // system dump: 6
};

export type LauncherContainer = 'workspace' | 'hotseat';

export type LauncherWidgetType = 'clock' | 'weather' | 'wmr';

export type LauncherWallpaper = { kind: 'image'; imageUrl: string };

export type LauncherItem =
  | { id: string; kind: 'app'; appId: AppId }
  | { id: string; kind: 'folder'; folderId: string }
  | { id: string; kind: 'widget'; widgetType: 'clock' | 'weather' }
  | { id: string; kind: 'widget'; widgetType: 'wmr'; widgetId: string; variant: string; previewUrl: string; xmlBaseUrl?: string };

export type LauncherPlacement = {
  itemId: string;
  container: LauncherContainer;
  /** workspace only */
  screenId?: string;
  cellX: number;
  cellY: number;
  spanX: number;
  spanY: number;
};

export type LauncherScreen = {
  id: string;
  placements: LauncherPlacement[];
};

export type LauncherFolder = {
  id: string;
  name: string;
  /** Folder content (apps only, v1). */
  items: AppId[];
};

export type LauncherLayout = {
  version: typeof LAUNCHER_LAYOUT_VERSION;
  grid: LauncherGrid;

  /** All workspace pages */
  screens: LauncherScreen[];

  /** Hotseat placements (single row, separate container) */
  hotseat: LauncherPlacement[];

  /**
   * Item registry.
   * - Every placement references an itemId here.
   * - Folder items reference `folders[folderId]`.
   */
  items: Record<string, LauncherItem>;

  folders: Record<string, LauncherFolder>;

  wallpaper: LauncherWallpaper;

  /**
   * Apps intentionally hidden from the desktop (system: apps can live only in app drawer).
   * We keep this to avoid reconcile re-adding icons the user removed.
   */
  hiddenApps: AppId[];
};
